window.__votdWeek && window.__votdWeek({"week":"2028-01-17","reading":"1 Nephi 11–15","days":[{"d":"2028-01-17","ref":"1 Nephi 11:13","b":"1 Nephi","c":11,"v":13,"he":"וָאַבִּיט וָאֵרֶא אֶת־הָעִיר הַגְּדוֹלָה יְרוּשָׁלַיִם וְגַם עָרִים אֲחֵרוֹת וָאֵרֶא אֶת־עִיר נָצְרַת וּבְעִיר נָצְרַת וָאֵרֶא עַלְמָה וְהִיא יְפַת־מַרְאֶה וּלְבָנָה עַד־מְאֹד׃","en":"And it came to pass that I looked and beheld the great city of Jerusalem, and also other cities. And I beheld the city of Nazareth; and in the city of Nazareth I beheld a virgin, and she was exceedingly fair and white."},{"d":"2028-01-18","ref":"1 Nephi 11:18","b":"1 Nephi","c":11,"v":18,"he":"וַיֹּאמֶר אֵלַי הִנֵּה הָעַלְמָה אֲשֶׁר רָאִיתָ הִיא אֵם בֶּן־אֱלֹהִים כְּדֶרֶךְ בָּשָׂר׃","en":"And he said unto me: Behold, the virgin whom thou seest is the mother of the Son of God, after the manner of the flesh."},{"d":"2028-01-19","ref":"1 Nephi 12:7","b":"1 Nephi","c":12,"v":7,"he":"וָאֵרֶא גַם־אֲנִי וָאָעִיד כִּי נָפַל רוּחַ־הַקֹּדֶשׁ עַל־שְׁנֵים עָשָׂר אֲחֵרִים וַיִּמָּשְׁחוּ מֵאֱלֹהִים וַיִּבָּחֲרוּ׃","en":"And I also saw and bear record that the Holy Ghost fell upon twelve others; and they were ordained of God, and chosen."},{"d":"2028-01-20","ref":"1 Nephi 12:10","b":"1 Nephi","c":12,"v":10,"he":"וְיִשְׁפְּטוּ שְׁנֵים עָשָׂר הַמְשָׁרְתִים הָאֵלֶּה אֲשֶׁר חָזִיתָ אֶת־זַרְעֶךָ וְהִנֵּה צַדִּיקִים הֵמָּה לְעוֹלָם כִּי מֵאֱמוּנָתָם בְּשֵׂה־אֱלֹהִים הֻלְבְּנוּ בִגְדֵיהֶם בְּדָמוֹ׃","en":"And these twelve ministers whom thou beholdest shall judge thy seed. And, behold, they are righteous forever; for because of their faith in the Lamb of God their garments are made white in his blood."},{"d":"2028-01-21","ref":"1 Nephi 14:21","b":"1 Nephi","c":14,"v":21,"he":"הִנֵּה יִרְאֶה וְיִכְתֹּב אֶת־יֶתֶר הַדְּבָרִים הָאֵלֶּה אַף וְגַם דְּבָרִים רַבִּים אֲשֶׁר הָיוּ׃","en":"Behold, he shall see and write the remainder of these things; yea, and also many things which have been."},{"d":"2028-01-22","ref":"1 Nephi 14:30","b":"1 Nephi","c":14,"v":30,"he":"וְעַתָּה אֲכַלֶּה לְדַבֵּר עַל־הַדְּבָרִים אֲשֶׁר רָאִיתִי בְּהִנָּשְׂאִי בְּרוּחַ וְאִם־לֹא נִכְתְּבוּ כׇּל־הַדְּבָרִים אֲשֶׁר רָאִיתִי אֱמֶת הַדְּבָרִים אֲשֶׁר כָּתַבְתִּי כֵּן הוּא אָמֵן׃","en":"And now I make an end of speaking concerning the things which I saw while I was carried away in the Spirit; and if all the things which I saw are not written, the things which I have written are true. And thus it is. Amen."},{"d":"2028-01-23","ref":"1 Nephi 15:12","b":"1 Nephi","c":15,"v":12,"he":"הִנֵּה אָמַרְתִּי לָכֶם בְּרוּחַ יְהוָה אֲשֶׁר בַּאֲבוֹתֵינוּ נִמְשַׁל בֵּית־יִשְׂרָאֵל לְעֵץ זַיִת וְהִנֵּה הֲלֹא נִגְדַעְנוּ מִבֵּית יִשְׂרָאֵל וַהֲלֹא עָנָף אֲנַחְנוּ מִבֵּית יִשְׂרָאֵל׃","en":"Behold, I say unto you, that the house of Israel was compared unto an olive tree, by the Spirit of the Lord which was in our father; and behold are we not broken off from the house of Israel, and are we not a branch of the house of Israel?"}]});
